    @Test
    public void secretInfo() throws Exception {

        String appkey = "b8366e81a1d21ceb035d09a6c5251587e77c4309";

        String configStr = "";
        String BLINK_SECRET_KEY = EnvReaderUtil.getEnv(SysConstant.BLINK_SECRET_KEY);

        String json = AESUtils.decrypt(AESUtils.keyFromBase64(BLINK_SECRET_KEY),configStr);
        List<ChannelSecretKey> channelSecretConfigs = JacksonUtil.fromJsonToList(json, ChannelSecretKey.class);

//        System.out.println(channelSecretConfigs);

        ChannelSecretKey secretKey = channelSecretConfigs.stream().filter(key->key.getAppKey().equals(appkey)).findFirst().orElse(null);

        System.out.println(secretKey);
    }


